import { useCallback, useRef } from "react";

export const POP_B64 = "data:audio/wav;base64,";
export const DING_B64 = "data:audio/wav;base64,";

const isSoundEnabled = () => {
  try {
    const saved = localStorage.getItem("ha_sound");
    if (!saved) return true;
    return JSON.parse(saved).enabled !== false;
  } catch {
    return true;
  }
};

const playAudio = (audio: HTMLAudioElement | null) => {
  if (!audio || !isSoundEnabled()) return;
  audio.currentTime = 0;
  audio.play().catch(() => {});
};

export function useSound() {
  const popAudio = useRef<HTMLAudioElement | null>(null);
  const dingAudio = useRef<HTMLAudioElement | null>(null);

  if (typeof window !== "undefined") {
    if (!popAudio.current) popAudio.current = new Audio(POP_B64);
    if (!dingAudio.current) dingAudio.current = new Audio(DING_B64);
  }

  const playPop = useCallback(() => {
    playAudio(popAudio.current);
  }, []);

  const playSuccess = useCallback(() => {
    playAudio(dingAudio.current);
  }, []);

  return { playPop, playSuccess };
}
